const CAT=[
{id:'b1',type:'Road',name:'Trek Domane AL 2',price:850,picture:'🚴',detail:'2021 · 54 cm · Excellent'},
{id:'b2',type:'Road',name:'Specialized Allez',price:620,picture:'🚴',detail:'2019 · 52 cm · Good'},
{id:'b3',type:'Road',name:'Giant Contend 3',price:480,picture:'🚴',detail:'2018 · 56 cm · Good'},
{id:'b4',type:'Road',name:'Cannondale Synapse',price:1250,picture:'🚴',detail:'2022 · 54 cm · Like new'},
{id:'b5',type:'Mountain',name:'Trek Marlin 6',price:540,picture:'🚵',detail:'2021 · M · Good'},
{id:'b6',type:'Mountain',name:'Giant Talon 2',price:690,picture:'🚵',detail:'2020 · L · Excellent'},
{id:'b7',type:'Mountain',name:'Specialized Rockhopper',price:780,picture:'🚵',detail:'2022 · M · Like new'},
{id:'b8',type:'Mountain',name:'Santa Cruz Chameleon',price:1650,picture:'🚵',detail:'2021 · L · Excellent'},
{id:'b9',type:'City',name:'Brooklyn Bedford 8',price:320,picture:'🚲',detail:'2017 · One size · Fair'},
{id:'b10',type:'City',name:'Specialized Sirrus X 2',price:610,picture:'🚲',detail:'2021 · M · Good'},
{id:'b11',type:'City',name:'Priority Continuum',price:950,picture:'🚲',detail:'2020 · L · Excellent'},
{id:'b12',type:'City',name:'Retrospec Beaumont',price:260,picture:'🚲',detail:'2019 · S · Good'}
];
const money=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});
function recalc(s){
 const types=[];
 if(s.fRoad)types.push('Road');
 if(s.fMountain)types.push('Mountain');
 if(s.fCity)types.push('City');
 let lo=Number(s.priceRange[0]),hi=Number(s.priceRange[1]);
 if(!isFinite(lo))lo=0;
 if(!isFinite(hi))hi=2000;
 if(lo>hi){const t=lo;lo=hi;hi=t;}
 let rows=CAT.filter(b=>b.price>=lo&&b.price<=hi&&(types.length===0||types.indexOf(b.type)>=0));
 rows.sort((a,b)=>s.sort==='desc'?b.price-a.price:a.price-b.price);
 s.results=rows.map(b=>({id:b.id,picture:b.picture,name:b.name,priceText:money.format(b.price),detail:b.detail}));
 s.countText=rows.length+' of 12';
}
const s=input.state,e=input.event,v=e.value;
if(e.type==='action'){
 if(e.actionId==='priceRange'&&Array.isArray(v)){
  let a=Number(v[0]),b=Number(v[1]);
  if(!isFinite(a))a=0;
  if(!isFinite(b))b=2000;
  s.priceRange=[Math.min(a,b),Math.max(a,b)];
 }
 if(e.actionId==='sort')s.sort=v==='desc'?'desc':'asc';
 if(e.actionId==='reset'){s.priceRange=[0,2000];s.sort='asc';s.fRoad=false;s.fMountain=false;s.fCity=false;s.fAll=true;}
 if(e.actionId==='fAll'){s.fAll=!!v;if(v){s.fRoad=false;s.fMountain=false;s.fCity=false;}}
 if(e.actionId==='fRoad'||e.actionId==='fMountain'||e.actionId==='fCity'){s[e.actionId]=!!v;s.fAll=!(s.fRoad||s.fMountain||s.fCity);}
 recalc(s);
}
return {state:s};
